pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 amount1, uint256 amount2, uint256 withdrawAmount, address actor1, address actor2) public {
        // Keep amounts within reasonable bounds to avoid overflow and ensure contract has enough balance
        vm.assume(amount1 <= 1e36);
        vm.assume(amount2 <= 1e36);
        vm.assume(withdrawAmount <= 1e36);
        vm.assume(actor1 != address(0) && actor2 != address(0));
        vm.assume(actor1 != actor2);

        // Fund actors and have them deposit into C via fallback
        vm.deal(actor1, amount1);
        vm.prank(actor1);
        (bool s1,) = address(c).call{value: amount1}("");
        require(s1, "deposit1 failed");

        vm.deal(actor2, amount2);
        vm.prank(actor2);
        (bool s2,) = address(c).call{value: amount2}("");
        require(s2, "deposit2 failed");

        // Choose the actor for withdrawal (must be one of the two)
        address withdrawingActor = (withdrawAmount % 2 == 0) ? actor1 : actor2;
        uint256 maxWithdraw = c.balances(withdrawingActor);
        vm.assume(maxWithdraw >= withdrawAmount);
        // Ensure the contract has enough balance to send; this is guaranteed by the deposits

        // Perform the withdrawal
        vm.prank(withdrawingActor);
        c.withdraw();

        // Calculate total sum of balances for both actors
        uint256 sumBalances = c.balances(actor1) + c.balances(actor2);
        // Invariant: sum of all balances must equal contract's ether balance
        assertEq(sumBalances, address(c).balance);
    }
}

