        attacker.triggerWithdraw();

        // After all calls, the total balance in the mapping must match the contract's ETH balance
        uint256 totalBalance = c.balances(address(attacker));
        assertEq(totalBalance, address(c).balance, "Sum of balances must equal contract ETH balance");
    }
