pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 amount, bool revertOnReceive) public {
        vm.assume(amount > 0);
        address sender = makeAddr("sender");
        vm.deal(sender, amount);

        // Deploy an adversarial receiver that optionally reverts
        RevertingReceiver receiver = new RevertingReceiver(revertOnReceive);
        address receiverAddr = address(receiver);

        // Fund c via the receiver so balances[receiverAddr] > 0
        vm.prank(receiverAddr);
        (bool fundOk,) = address(c).call{value: amount}("");
        require(fundOk, "funding c failed");

        uint256 balanceBefore = receiverAddr.balance;
        uint256 cBefore = address(c).balance;

        // The receiver initiates withdrawal; this prank ensures msg.sender == receiverAddr
        vm.prank(receiverAddr);
        try c.withdraw() {
            // Withdrawal succeeded
            uint256 balanceAfter = receiverAddr.balance;
            // Since the call succeeded, receiver got the ether and its balance increased
            assertTrue(balanceAfter == balanceBefore + amount);
        } catch {
            // Withdrawal call reverted (e.g. __lock_modifier0 prevented re-entry?)
            // In either case, we cannot directly observe the state change of a failed inner call
            // because the entire withdraw reverted. For the property, we need to observe the case
            // where the external call fails but withdraw does not revert -> the buggy version.
            // We use a separate scenario below where the call fails silently.
        }

        // Now test the case where the call fails and the buggy version does not revert
        // We need to bypass the modifier lock. For simplicity, we perform a fresh setup.
        C c2 = new C();
        RevertingReceiver recv2 = new RevertingReceiver(true);
        address recvAddr2 = address(recv2);
        vm.deal(recvAddr2, amount);
        vm.prank(recvAddr2);
        (bool fundOk2,) = address(c2).call{value: amount}("");
        require(fundOk2);

        uint256 recvBalBefore = recvAddr2.balance;
        vm.prank(recvAddr2);
        // The buggy version's withdraw does not require(__sent_result100),
        // so if call fails, it continues and zeroes balance.
        // The correct version will revert because require(__sent_result100) fails.
        bool correctReverted = false;
        bool bugReverted = false;
        // We cannot test both versions in the same run without having the buggy contract;
        // but the test file is compiled and run against exactly one version of C.
        // The property: "For any address a with positive balance, after withdraw() called by a,
        // either the call succeeds and a's balance becomes 0, or the call fails and a's balance remains unchanged."
        // The reference version satisfies this because it reverts on failed call, making the whole withdraw revert,
        // so balances[msg.sender] is never zeroed. The buggy version breaks it: failed call -> balance zeroed.
        // To observe this, we check that c2's balances[recvAddr2] remains >0 if the call fails.
        // Since the reference version reverts the whole transaction, the balance stays unchanged.
        // We assert that after a failed call, the sender's balance in c2 is still >0.
        try c2.withdraw() {
            // This path means the call to receiver succeeded or the contract didn't revert;
            // With the reverting receiver, the call will fail, so the reference version would revert.
            // If we get here, the buggy version executed and zeroed the balance.
            uint256 balAfter = c2.balances(recvAddr2);
            assertTrue(balAfter == 0); // This assertion fails on reference, passes on buggy? We need it the other way.
            // We want the assertion to PASS on reference and FAIL on buggy.
            // If we get here on the buggy version, balance became 0, so asserting balAfter == 0 is TRUE -> passes.
            // That's opposite. We need an assertion that is TRUE for reference, FALSE for buggy.
        } catch {
            // Reference version reverted; balance unchanged.
            uint256 balAfter = c2.balances(recvAddr2);
            assertTrue(balAfter == amount); // unchanged
        }
        // Actually the above doesn't work cleanly for both versions in one test because try/catch catches reverts,
        // and the assertion inside catch is only reached on reference. On buggy, catch not entered, and we can assert false.
        // Better: after withdraw, in all cases, c2.balances[recvAddr2] must equal amount if the call failed.
        // We'll restructure the fuzz test to properly assert the invariant.
